package org.bytefred.ktoy.core

/**
 * C compiler verification fixtures, embedded as strings (commonTest has
 * no portable filesystem access).
 *
 * For each example: the C source and the GOLDEN .toys produced by pytoy's
 * compile_source(src, name). ktoy's compileSource(src, name) must
 * reproduce the golden output byte-for-byte. The `name` is the .toyc file
 * basename (with extension), matching pytoy's scripts/build_examples.py, so
 * the "# Generated by toycc from <name>" headers agree.
 *
 * Frozen fixtures: generated once from pytoy's examples/c/ and compiler (that
 * generator is gone, ktoy no longer uses pytoy). The C sources here are not
 * kept in sync with examples/; they only pin the compiler's output.
 * 04-io/ examples are excluded (read/write I/O, not headless-deterministic).
 */

data class CExample(val name: String, val cSource: String, val expectedToys: String)

val C_EXAMPLES: List<CExample> = listOf(
