        store v_x
        # int y = ...
        load  c_60
        store v_y
        # int a = ...
        load  v_x
        and   v_y
        store v_a
        # int c = ...
        load  v_x
        xor   v_y
        store v_c
        # a = ...
        load  c_2
        store t1
        load  v_a
        right
        right
        store v_a
        # a = ...
        load  c_1
        store t2
        load  v_a
        left
        store v_a
        # return
        load  v_c
        and   c_15
        store t3
        load  v_a
        add   t3
        stop
        stop            # fallthrough halt

# data
v_x: 0
v_y: 0
v_a: 0
v_c: 0
t1: 0
t2: 0
t3: 0
c_1: 1
c_2: 2
c_15: 15
c_60: 60
c_240: 240
